{"security_risk": "LOW", "summary": "Extract handbook text and locate key spec sections", "command": "python - <<'PY'
from pypdf import PdfReader
import re
path='/app/data/handbook.pdf'
r=PdfReader(path)
print('pages',len(r.pages))
keywords=['preheat','ramp','slope','tal','time above liquidus','liquidus','peak','conveyor','speed','dwell']
found={k:[] for k in keywords}
for i,p in enumerate(r.pages, start=1):
    txt=p.extract_text() or ''
    low=txt.lower()
    for k in keywords:
        if k in low:
            found[k].append(i)
# print summary
for k in keywords:
    pages=found[k]
    if pages:
        print(k, 'pages', pages[:20], '...' if len(pages)>20 else '')

# show snippets around a few occurrences per keyword group
want_pages=sorted(set(found['preheat'][:3]+found['ramp'][:3]+found['tal'][:3]+found['peak'][:3]+found['conveyor'][:3]))
print('\npreview pages',want_pages)
for i in want_pages:
    txt=(r.pages[i-1].extract_text() or '').splitlines()
    print('\n--- page',i,'---')
    for line in txt[:80]:
        if line.strip():
            print(line)
PY"}

