{"security_risk":"LOW","summary":"Search handbook text for explicit ramp rate and preheat region wording", "command":"python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
pat=re.compile(r'.{0,60}(preheat|100\s*\D?c|150\s*\D?c|2.?c\/second|wetting time|30\s*to\s*60).{0,60}', re.I)
for i,p in enumerate(r.pages, start=1):
    txt=p.extract_text() or ''
    if i in [5,6,7]:
        print('\n=== page',i,'===')
        for m in pat.finditer(txt.replace('\n',' ')):
            s=m.group(0)
            if any(k.lower() in s.lower() for k in ['preheat','100','150','2','wetting','30','60']):
                print(s.strip())
PY"}

