{"security_risk": "MEDIUM", "summary": "Create deterministic solver script computing q01-q05 JSON outputs", "command": "create", "path": "/app/solve_reflow.py", "file_text": "import json
import math
import re
from pathlib import Path

import pandas as pd
from pypdf import PdfReader

DATA_DIR = Path("/app/data")
OUT_DIR = Path("/app/output")


def r2(x):
    if x is None:
        return None
    try:
        xf = float(x)
    except Exception:
        return None
    if math.isnan(xf) or math.isinf(xf):
        return None
    return float(round(xf, 2))


def load_handbook_cfg(handbook_path: Path) -> dict:
    reader = PdfReader(str(handbook_path))
    text = "\n".join((p.extract_text() or "") for p in reader.pages)

    # Preheat definition and ramp limit (handbook page 5).
    # "... preheat ... between 100°C to 150°C. ... rate of rise ... less than 2°C/second."
    m_preheat = re.search(r"between\s+(\d+)\s*\D?c\s*to\s*(\d+)\s*\D?c", text, flags=re.I)
    if not m_preheat:
        raise RuntimeError("Could not locate preheat temperature range in handbook")
    preheat_tmin_c = float(m_preheat.group(1))
    preheat_tmax_c = float(m_preheat.group(2))

    m_ramp = re.search(r"less\s+than\s+(\d+(?:\.\d+)?)\s*\D?c\s*/\s*second", text, flags=re.I)
    if not m_ramp:
        raise RuntimeError("Could not locate ramp-rate limit in handbook")
    ramp_limit_c_per_s = float(m_ramp.group(1))

    # Wetting time / TAL window (handbook page 5).
    # "wetting time is normally 30 to 60 seconds"
    m_tal = re.search(r"wetting\s+time\s+is\s+normally\s+(\d+)\s+to\s+(\d+)\s+seconds", text, flags=re.I)
    if not m_tal:
        raise RuntimeError("Could not locate wetting time (TAL) window in handbook")
    tal_min_s = float(m_tal.group(1))
    tal_max_s = float(m_tal.group(2))

    # Peak margin above melting point (handbook page 5).
    # "must be exceeded by approximately 20°C"
    m_peak = re.search(r"exceeded\s+by\s+approximately\s+(\d+)\s*\D?c", text, flags=re.I)
    if not m_peak:
        raise RuntimeError("Could not locate peak temperature margin in handbook")
    peak_margin_c = float(m_peak.group(1))

    # Conveyor feasibility equations (handbook page 14). Validate presence of key terms.
    if "LINE SPEED" not in text.upper() or "BOARDS PER MINUTE" not in text.upper() or "LOAD FACTOR" not in text.upper():
        raise RuntimeError("Could not validate conveyor speed sizing guidance in handbook")

    return {
        "preheat_tmin_c": preheat_tmin_c,
        "preheat_tmax_c": preheat_tmax_c,
        "ramp_limit_c_per_s": ramp_limit_c_per_s,
        "tal_min_s": tal_min_s,
        "tal_max_s": tal_max_s,
        "peak_margin_c": peak_margin_c,
    }


def max_positive_slope_preheat(df_tc: pd.DataFrame, preheat_tmax_c: float) -> float | None:
    g = df_tc.sort_values("time_s", kind="mergesort")
    t = g["time_s"].to_numpy(dtype=float)
    y = g["temp_c"].to_numpy(dtype=float)
    best = None
    for i in range(1, len(g)):
        dt = t[i] - t[i - 1]
        if dt <= 0:
            continue
        # Preheat is the portion of the profile up to the handbook's stated preheat ceiling.
        if y[i - 1] <= preheat_tmax_c and y[i] <= preheat_tmax_c:
            s = (y[i] - y[i - 1]) / dt
            if s <= 0:
                continue
            best = s if best is None else max(best, s)
    return best


def time_above_threshold_s(df_tc: pd.DataFrame, thr_c: float) -> float | None:
    g = df_tc.sort_values("time_s", kind="mergesort")
    t = g["time_s"].to_numpy(dtype=float)
    y = g["temp_c"].to_numpy(dtype=float)
    if len(g) < 2:
        return None

    total = 0.0

    def is_above(v):
        # Handbook wording: "above the melting point" (strictly >).
        return v > thr_c

    for i in range(1, len(g)):
        t0, t1 = t[i - 1], t[i]
        y0, y1 = y[i - 1], y[i]
        if t1 <= t0:
            continue

        a0, a1 = is_above(y0), is_above(y1)
        if a0 and a1:
            total += (t1 - t0)
            continue

        if y1 == y0:
            continue

        # crossing occurs when the segment straddles thr (including equality at the lower end)
        crosses = (y0 <= thr_c < y1) or (y1 <= thr_c < y0)
        if not crosses:
            continue

        frac = (thr_c - y0) / (y1 - y0)
        tcross = t0 + frac * (t1 - t0)

        if (y0 <= thr_c and y1 > thr_c):
            total += (t1 - tcross)
        elif (y1 <= thr_c and y0 > thr_c):
            total += (tcross - t0)

    return total


def select_tc_max_metric(metric_by_tc: dict[str, float | None]) -> tuple[str | None, float | None]:
    items = [(tc, v) for tc, v in metric_by_tc.items() if v is not None]
    if not items:
        return None, None
    tc, v = sorted(items, key=lambda x: (-x[1], x[0]))[0]
    return tc, v


def select_tc_min_metric(metric_by_tc: dict[str, float | None]) -> tuple[str | None, float | None]:
    items = [(tc, v) for tc, v in metric_by_tc.items() if v is not None]
    if not items:
        return None, None
    tc, v = sorted(items, key=lambda x: (x[1], x[0]))[0]
    return tc, v


def tal_run_status_and_tc(
    tal_by_tc: dict[str, float | None],
    min_req: float | None,
    max_req: float | None,
) -> tuple[str | None, float | None, str]:
    items = [(tc, tal) for tc, tal in tal_by_tc.items() if tal is not None]
    if not items:
        return None, None, "non-compliant"

    have_any_bound = (min_req is not None) or (max_req is not None)

    def v_low(tal):
        return 0.0 if min_req is None else max(0.0, float(min_req) - float(tal))

    def v_high(tal):
        return 0.0 if max_req is None else max(0.0, float(tal) - float(max_req))

    violating = []  # (max_violation, tc_id, tal)
    for tc, tal in items:
        mv = max(v_low(tal), v_high(tal))
        if mv > 0:
            violating.append((mv, tc, tal))

    if violating:
        any_low = any(v_low(tal) > 0 for _, _, tal in violating)
        any_high = any(v_high(tal) > 0 for _, _, tal in violating)

        if any_low and not any_high:
            tc, tal = select_tc_min_metric({tc: tal for tc, tal in items})
            return tc, tal, "non-compliant"
        if any_high and not any_low:
            tc, tal = select_tc_max_metric({tc: tal for tc, tal in items})
            return tc, tal, "non-compliant"

        mv, tc, tal = sorted(violating, key=lambda x: (-x[0], x[1]))[0]
        return tc, tal, "non-compliant"

    status = "compliant" if have_any_bound else "non-compliant"
    # Conservative representative choice (coldest / lowest TAL).
    tc, tal = select_tc_min_metric({tc: tal for tc, tal in items})
    return tc, tal, status


def main() -> None:
    OUT_DIR.mkdir(parents=True, exist_ok=True)

    cfg = load_handbook_cfg(DATA_DIR / "handbook.pdf")

    df_mes = pd.read_csv(DATA_DIR / "mes_log.csv")
    df_tc = pd.read_csv(DATA_DIR / "thermocouples.csv")
    df_def = pd.read_csv(DATA_DIR / "test_defects.csv")

    # normalize ids as strings
    for df in (df_mes, df_tc, df_def):
        df["run_id"] = df["run_id"].astype(str)
    df_tc["tc_id"] = df_tc["tc_id"].astype(str)

    run_ids = sorted(df_mes["run_id"].unique())

    # Pre-group thermocouple data
    tc_groups = {
        (rid, tcid): g
        for (rid, tcid), g in df_tc.groupby(["run_id", "tc_id"], sort=False)
    }

    # Per-run computations
    ramp_selected = {}
    ramp_violations = []

    tal_rows = []
    tal_run_ok = {}

    peak_selected = {}
    peak_failing = []
    peak_run_ok = {}

    conv_rows = []
    conv_run_ok = {}

    # Q01: ramp in preheat
    for rid in run_ids:
        tcs = sorted(df_tc.loc[df_tc.run_id == rid, "tc_id"].unique())
        ramp_by_tc = {}
        for tcid in tcs:
            g = tc_groups.get((rid, tcid))
            ramp_by_tc[tcid] = max_positive_slope_preheat(g, cfg["preheat_tmax_c"]) if g is not None else None

        sel_tc, sel_ramp = select_tc_max_metric(ramp_by_tc)
        ramp_selected[rid] = {
            "tc_id": sel_tc,
            "max_preheat_ramp_c_per_s": r2(sel_ramp),
        }

        if sel_ramp is None or sel_ramp > cfg["ramp_limit_c_per_s"]:
            ramp_violations.append(rid)

    q01 = {
        "ramp_rate_limit_c_per_s": r2(cfg["ramp_limit_c_per_s"]),
        "violating_runs": sorted(ramp_violations),
        "max_ramp_by_run": {rid: ramp_selected[rid] for rid in run_ids},
    }

    # Q02: TAL (time above liquidus)
    for rid in run_ids:
        liquidus = df_mes.loc[df_mes.run_id == rid, "solder_liquidus_c"].iloc[0]
        if pd.isna(liquidus):
            liquidus = None
        else:
            liquidus = float(liquidus)

        tcs = sorted(df_tc.loc[df_tc.run_id == rid, "tc_id"].unique())
        tal_by_tc = {}
        for tcid in tcs:
            g = tc_groups.get((rid, tcid))
            if g is None or liquidus is None:
                tal_by_tc[tcid] = None
            else:
                tal_by_tc[tcid] = time_above_threshold_s(g, liquidus)

        sel_tc, sel_tal, status = tal_run_status_and_tc(
            tal_by_tc,
            cfg["tal_min_s"],
            cfg["tal_max_s"],
        )
        tal_rows.append(
            {
                "run_id": rid,
                "tc_id": sel_tc,
                "tal_s": r2(sel_tal),
                "required_min_tal_s": r2(cfg["tal_min_s"]),
                "required_max_tal_s": r2(cfg["tal_max_s"]),
                "status": status,
            }
        )

        # run-level ok: must have at least one computed TAL and all TCs within window
        if status != "compliant":
            tal_run_ok[rid] = False
        else:
            # ensure no hidden violations
            ok = True
            for v in tal_by_tc.values():
                if v is None:
                    ok = False
                    break
                if v < cfg["tal_min_s"] or v > cfg["tal_max_s"]:
                    ok = False
                    break
            tal_run_ok[rid] = ok

    tal_rows = sorted(tal_rows, key=lambda x: x["run_id"])

    # Q03: peak temperature requirement
    for rid in run_ids:
        liquidus = df_mes.loc[df_mes.run_id == rid, "solder_liquidus_c"].iloc[0]
        if pd.isna(liquidus):
            liquidus = None
        else:
            liquidus = float(liquidus)
        required_min_peak = None if liquidus is None else (liquidus + cfg["peak_margin_c"])

        tcs = sorted(df_tc.loc[df_tc.run_id == rid, "tc_id"].unique())
        peak_by_tc = {}
        for tcid in tcs:
            g = tc_groups.get((rid, tcid))
            peak_by_tc[tcid] = None if g is None else float(g["temp_c"].max())

        sel_tc, sel_peak = select_tc_min_metric(peak_by_tc)
        peak_selected[rid] = {
            "tc_id": sel_tc,
            "peak_temp_c": r2(sel_peak),
            "required_min_peak_c": r2(required_min_peak),
        }

        failing = False
        if sel_peak is None or required_min_peak is None:
            failing = True
        elif sel_peak < required_min_peak:
            failing = True

        if failing:
            peak_failing.append(rid)
            peak_run_ok[rid] = False
        else:
            peak_run_ok[rid] = True

    q03 = {
        "failing_runs": sorted(peak_failing),
        "min_peak_by_run": {rid: peak_selected[rid] for rid in run_ids},
    }

    # Q04: conveyor speed feasibility (handbook page 14 line-speed equation)
    for rid in run_ids:
        row = df_mes.loc[df_mes.run_id == rid].iloc[0]
        bpm = row.get("boards_per_min")
        length_cm = row.get("board_length_cm")
        load_factor = row.get("loading_factor")
        actual_speed = row.get("conveyor_speed_cm_min")

        if pd.isna(bpm) or pd.isna(length_cm) or pd.isna(load_factor) or load_factor == 0:
            req = None
        else:
            req = float(bpm) * float(length_cm) / float(load_factor)

        meets = False
        if req is not None and not pd.isna(actual_speed):
            meets = float(actual_speed) >= req

        conv_rows.append(
            {
                "run_id": rid,
                "required_min_speed_cm_min": r2(req),
                "actual_speed_cm_min": r2(None if pd.isna(actual_speed) else float(actual_speed)),
                "meets": bool(meets),
            }
        )
        conv_run_ok[rid] = bool(meets)

    conv_rows = sorted(conv_rows, key=lambda x: x["run_id"])

    # Q05: best run per board_family (quality + efficiency)
    # Quality: prefer higher first-pass yield from SUMMARY rows.
    df_summary = df_def[df_def["inspection_stage"].astype(str).str.upper() == "SUMMARY"].copy()
    # Ensure one row per run; if duplicates exist, take the first deterministically.
    df_summary = df_summary.sort_values(["run_id", "lot_id"], kind="mergesort").drop_duplicates(["run_id"], keep="first")

    summary_by_run = df_summary.set_index("run_id")[
        ["fp_yield_pct", "units_scrap", "units_tested"]
    ].to_dict(orient="index")

    fam_rows = []

    for fam, g in df_mes.groupby("board_family", sort=True):
        candidates = []
        for _, r in g.iterrows():
            rid = str(r["run_id"])
            s = summary_by_run.get(rid, {})
            fp = s.get("fp_yield_pct")
            scrap = s.get("units_scrap")
            bpm = r.get("boards_per_min")
            downtime = r.get("downtime_s")

            process_ok = (
                (ramp_selected[rid]["max_preheat_ramp_c_per_s"] is not None)
                and (ramp_selected[rid]["max_preheat_ramp_c_per_s"] <= r2(cfg["ramp_limit_c_per_s"]))
                and tal_run_ok.get(rid, False)
                and peak_run_ok.get(rid, False)
                and conv_run_ok.get(rid, False)
            )

            # Sorting keys: compliant first, then yield desc, scrap asc, bpm desc, downtime asc.
            # Nulls pushed to the end deterministically.
            def null_last_desc(x):
                return (x is None or (isinstance(x, float) and math.isnan(x)), -(x if x is not None and not (isinstance(x, float) and math.isnan(x)) else -1e18))

            def null_last_asc(x):
                return (x is None or (isinstance(x, float) and math.isnan(x)), (x if x is not None and not (isinstance(x, float) and math.isnan(x)) else 1e18))

            candidates.append(
                {
                    "run_id": rid,
                    "process_ok": process_ok,
                    "fp": None if pd.isna(fp) else float(fp),
                    "scrap": None if pd.isna(scrap) else float(scrap),
                    "bpm": None if pd.isna(bpm) else float(bpm),
                    "downtime": None if pd.isna(downtime) else float(downtime),
                }
            )

        # Rank candidates
        candidates_sorted = sorted(
            candidates,
            key=lambda x: (
                0 if x["process_ok"] else 1,
                # yield desc
                (x["fp"] is None, -(x["fp"] if x["fp"] is not None else -1e18)),
                # scrap asc
                (x["scrap"] is None, (x["scrap"] if x["scrap"] is not None else 1e18)),
                # bpm desc
                (x["bpm"] is None, -(x["bpm"] if x["bpm"] is not None else -1e18)),
                # downtime asc
                (x["downtime"] is None, (x["downtime"] if x["downtime"] is not None else 1e18)),
                x["run_id"],
            ),
        )

        if not candidates_sorted:
            best = None
            runners = []
        else:
            best = candidates_sorted[0]["run_id"]
            runners = sorted([c["run_id"] for c in candidates_sorted[1:]])

        fam_rows.append(
            {
                "board_family": str(fam),
                "best_run_id": best,
                "runner_up_run_ids": runners,
            }
        )

    fam_rows = sorted(fam_rows, key=lambda x: x["board_family"])

    # Write outputs
    (OUT_DIR / "q01.json").write_text(json.dumps(q01, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (OUT_DIR / "q02.json").write_text(json.dumps(tal_rows, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (OUT_DIR / "q03.json").write_text(json.dumps(q03, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (OUT_DIR / "q04.json").write_text(json.dumps(conv_rows, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (OUT_DIR / "q05.json").write_text(json.dumps(fam_rows, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
"}

